const root='work/nss140',old='work/nss128/controlled-matched-aba-20261005205520-95105879',selected=JSON.parse(fs.readFileSync(old+'/selected-private.json')),frame=JSON.parse(fs.readFileSync(old+'/post-checkpoint-controlled-receipt-private.json'));const p=packetTemplate(mapClassifiedPair(frame,selected),'a'.repeat(32),59999);p.expected.nftables=p.expected.nftables.filter(x=>x.chain?.name!=='forward'&&x.rule?.chain!=='forward');
